import{_ as t,o as a,c as n,a2 as s}from"./chunks/framework.CNfFRqmr.js";const u=JSON.parse('{"title":"Web Search and Fetch Technical Design","description":"harness9 grants Agents real-time internet access through two built-in tools, web_search and web_fetch, requiring no A...","frontmatter":{"title":"Web Search and Fetch Technical Design","description":"harness9 grants Agents real-time internet access through two built-in tools, web_search and web_fetch, requiring no A..."},"headers":[],"relativePath":"docs/web-search.md","filePath":"docs/web-search.md"}'),i={name:"docs/web-search.md"};function o(r,e,c,d,l,p){return a(),n("div",null,[...e[0]||(e[0]=[s(`<h1 id="web-search-and-fetch-technical-design" tabindex="-1">Web Search and Fetch Technical Design <a class="header-anchor" href="#web-search-and-fetch-technical-design" aria-label="Permalink to &quot;Web Search and Fetch Technical Design&quot;">​</a></h1><p>harness9 grants Agents real-time internet access through two built-in tools, <code>web_search</code> and <code>web_fetch</code>, requiring no API Key and shipping with production-grade SSRF protection.</p><hr><h2 id="_1-design-decisions" tabindex="-1">1. Design Decisions <a class="header-anchor" href="#_1-design-decisions" aria-label="Permalink to &quot;1. Design Decisions&quot;">​</a></h2><h3 id="why-not-build-this-as-an-mcp-tool" tabindex="-1">Why not build this as an MCP tool <a class="header-anchor" href="#why-not-build-this-as-an-mcp-tool" aria-label="Permalink to &quot;Why not build this as an MCP tool&quot;">​</a></h3><p>DeepAgents and OpenCode fully outsource web capability to MCP servers, meaning zero configuration equals zero capability — users must install and configure a Tavily or Brave MCP themselves. harness9&#39;s philosophy is <strong>out-of-the-box readiness</strong>: DuckDuckGo requires no Key at all, <code>go-readability</code> is a pure Go library, and the entire capability chain depends on no external platform account.</p><h3 id="tools-stay-atomic-deep-search-lives-at-the-llm-layer" tabindex="-1">Tools stay atomic, deep search lives at the LLM layer <a class="header-anchor" href="#tools-stay-atomic-deep-search-lives-at-the-llm-layer" aria-label="Permalink to &quot;Tools stay atomic, deep search lives at the LLM layer&quot;">​</a></h3><p>The tools provide only two atomic capabilities: search (return result links) and fetch (return page content). Whether to keep following links, whether to expand the search terms, when to stop — these decisions are entirely delegated to the LLM within the ReAct loop. This is the shared design choice across six mainstream frameworks; the tool layer neither needs nor should embed search-tree traversal logic.</p><h3 id="why-inject-the-current-date" tabindex="-1">Why inject the current date <a class="header-anchor" href="#why-inject-the-current-date" aria-label="Permalink to &quot;Why inject the current date&quot;">​</a></h3><p>There is a gap between the LLM&#39;s knowledge cutoff (training cutoff) and the actual current time. Without date injection, an Agent tends to use the training cutoff year when searching, causing it to retrieve stale results when searching for &quot;the latest version.&quot; harness9 injects the real-time date via <code>time.Now().Format(&quot;2006-01-02&quot;)</code> into the base section of the System Prompt, so the Agent automatically perceives the current date in every session with no extra tool call needed.</p><hr><h2 id="_2-tool-interface" tabindex="-1">2. Tool Interface <a class="header-anchor" href="#_2-tool-interface" aria-label="Permalink to &quot;2. Tool Interface&quot;">​</a></h2><h3 id="web-search" tabindex="-1"><code>web_search</code> <a class="header-anchor" href="#web-search" aria-label="Permalink to &quot;\`web_search\`&quot;">​</a></h3><p>Searches the internet and returns a list of titles, URLs, and snippets.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th style="text-align:center;">Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>query</code></td><td>string</td><td style="text-align:center;">Yes</td><td>—</td><td>Search query; English yields better results</td></tr><tr><td><code>max_results</code></td><td>int</td><td style="text-align:center;">No</td><td>5</td><td>Number of results returned, range 1–10</td></tr></tbody></table><p><strong>Output format:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[1] Go 1.25 Release Notes</span></span>
<span class="line"><span>URL: https://go.dev/doc/go1.25</span></span>
<span class="line"><span>摘要: Go 1.25 introduces range-over-func, improved type inference...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[2] What&#39;s new in Go 1.25</span></span>
<span class="line"><span>URL: https://blog.golang.org/go1.25</span></span>
<span class="line"><span>摘要: The Go team is pleased to announce Go 1.25...</span></span></code></pre></div><h3 id="web-fetch" tabindex="-1"><code>web_fetch</code> <a class="header-anchor" href="#web-fetch" aria-label="Permalink to &quot;\`web_fetch\`&quot;">​</a></h3><p>Fetches the given URL and returns the main content in Markdown format.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th style="text-align:center;">Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>url</code></td><td>string</td><td style="text-align:center;">Yes</td><td>—</td><td>Target URL (http/https)</td></tr><tr><td><code>max_chars</code></td><td>int</td><td style="text-align:center;">No</td><td>8000</td><td>Maximum characters returned, capped at 32000</td></tr></tbody></table><p><strong>Output format:</strong></p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># Go 1.25 Release Notes</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">&gt; 来源：https://go.dev/doc/go1.25</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## New Features</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">...main content (Markdown format)...</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[内容已截断，已显示前 8000 字符]   ← only appears when the limit is exceeded</span></span></code></pre></div><hr><h2 id="_3-ssrf-protection-web-safety-go" tabindex="-1">3. SSRF Protection (<code>web_safety.go</code>) <a class="header-anchor" href="#_3-ssrf-protection-web-safety-go" aria-label="Permalink to &quot;3. SSRF Protection (\`web_safety.go\`)&quot;">​</a></h2><p>Every HTTP request is validated by <code>isSafeURL</code> before being sent, analogous to the sandbox protection <code>safe_path.go</code> provides for filesystem paths.</p><h3 id="check-chain" tabindex="-1">Check chain <a class="header-anchor" href="#check-chain" aria-label="Permalink to &quot;Check chain&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>URL input</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>① scheme validation: must be http or https, reject ftp / file etc.</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>② userinfo rejection: any URL containing user:pass@... format is rejected</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>③ DNS resolution: net.LookupHost(hostname)</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ├── resolution failure → fail-closed (reject the request)</span></span>
<span class="line"><span>  │              the first line of defense against DNS rebinding attacks</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>④ IP range check: check every resolved IP address</span></span></code></pre></div><h3 id="permanently-blocked-ip-ranges" tabindex="-1">Permanently blocked IP ranges <a class="header-anchor" href="#permanently-blocked-ip-ranges" aria-label="Permalink to &quot;Permanently blocked IP ranges&quot;">​</a></h3><table tabindex="0"><thead><tr><th>CIDR</th><th>Description</th><th style="text-align:center;">Configurable</th></tr></thead><tbody><tr><td><code>169.254.0.0/16</code></td><td>Link-local + AWS/Azure/GCP metadata endpoint</td><td style="text-align:center;">Permanently blocked</td></tr><tr><td><code>127.0.0.0/8</code></td><td>IPv4 loopback</td><td style="text-align:center;">Blocked by default</td></tr><tr><td><code>::1</code></td><td>IPv6 loopback (independently checked via <code>net.IPv6loopback</code>)</td><td style="text-align:center;">Blocked by default</td></tr><tr><td><code>10.0.0.0/8</code></td><td>RFC1918 private network</td><td style="text-align:center;">Blocked by default</td></tr><tr><td><code>172.16.0.0/12</code></td><td>RFC1918 private network</td><td style="text-align:center;">Blocked by default</td></tr><tr><td><code>192.168.0.0/16</code></td><td>RFC1918 private network</td><td style="text-align:center;">Blocked by default</td></tr><tr><td><code>100.64.0.0/10</code></td><td>CGNAT</td><td style="text-align:center;">Blocked by default</td></tr><tr><td><code>fe80::/10</code></td><td>IPv6 link-local (equivalent to IPv4 169.254.0.0/16)</td><td style="text-align:center;">Blocked by default</td></tr><tr><td><code>fc00::/7</code></td><td>IPv6 Unique Local Address (ULA) (equivalent to IPv4 RFC1918 private network)</td><td style="text-align:center;">Blocked by default</td></tr></tbody></table><h3 id="why-re-check-the-ip-after-dns-resolution" tabindex="-1">Why re-check the IP after DNS resolution <a class="header-anchor" href="#why-re-check-the-ip-after-dns-resolution" aria-label="Permalink to &quot;Why re-check the IP after DNS resolution&quot;">​</a></h3><p>An attacker can have a domain resolve first to a public IP to pass validation, then switch the resolution to an internal address within the DNS TTL window (DNS rebinding). Resolving first and then checking the IP cuts off this path — the IP <code>isSafeURL</code> receives is the real IP at the moment of the DNS query, not the hostname.</p><h3 id="ipv4-mapped-ipv6-normalization" tabindex="-1">IPv4-mapped IPv6 normalization <a class="header-anchor" href="#ipv4-mapped-ipv6-normalization" aria-label="Permalink to &quot;IPv4-mapped IPv6 normalization&quot;">​</a></h3><p><code>::ffff:169.254.169.254</code> is the IPv6 representation of <code>169.254.169.254</code>. The code normalizes IPv4-mapped IPv6 addresses to IPv4 via <code>ip.To4()</code>, ensuring internal addresses expressed in IPv6 form cannot bypass the CIDR check.</p><h3 id="redirect-chain-ssrf-protection" tabindex="-1">Redirect chain SSRF protection <a class="header-anchor" href="#redirect-chain-ssrf-protection" aria-label="Permalink to &quot;Redirect chain SSRF protection&quot;">​</a></h3><p><code>web_fetch</code>&#39;s <code>CheckRedirect</code> callback re-invokes <code>isSafeURL</code> on the new URL after every redirect, preventing an open-redirect → internal-network attack path:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>External URL → SSRF check ✓ → server 301 → internal URL → SSRF check ✗ (rejected)</span></span></code></pre></div><hr><h2 id="_4-html-content-extraction-pipeline-web-content-go" tabindex="-1">4. HTML Content Extraction Pipeline (<code>web_content.go</code>) <a class="header-anchor" href="#_4-html-content-extraction-pipeline-web-content-go" aria-label="Permalink to &quot;4. HTML Content Extraction Pipeline (\`web_content.go\`)&quot;">​</a></h2><p>After <code>web_fetch</code> retrieves HTML, it goes through a three-stage pipeline that converts it into LLM-friendly Markdown:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>HTML body (io.Reader)</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ▼</span></span>
<span class="line"><span>① Size limit (1MB)</span></span>
<span class="line"><span>    │ exceeded → return error</span></span>
<span class="line"><span>    ▼</span></span>
<span class="line"><span>② go-readability.FromReader()</span></span>
<span class="line"><span>    │ success → Article{Title, Content(HTML)}</span></span>
<span class="line"><span>    │ failure → go straight to fallback</span></span>
<span class="line"><span>    ▼</span></span>
<span class="line"><span>③ html-to-markdown.Convert(Article.Content)</span></span>
<span class="line"><span>    │ success → Markdown string</span></span>
<span class="line"><span>    │ failure → use Article.TextContent (plain text extracted by readability)</span></span>
<span class="line"><span>    ▼</span></span>
<span class="line"><span>④ assemblePage(rawURL, title, content, maxChars)</span></span>
<span class="line"><span>    │ assemble output: # title + &gt; source + content</span></span>
<span class="line"><span>    │ exceeds maxChars → truncate + append marker</span></span>
<span class="line"><span>    ▼</span></span>
<span class="line"><span>Markdown output</span></span></code></pre></div><p><strong>Fallback path</strong>: when <code>go-readability</code> fails entirely (e.g. minimal HTML or empty content), a simple text extraction is done using the <code>golang.org/x/net/html</code> tokenizer — skipping the contents of <code>&lt;script&gt;</code> and <code>&lt;style&gt;</code> tags and concatenating visible text nodes. This tokenizer is an indirect dependency within the Go standard library&#39;s scope, adding zero extra dependencies.</p><h3 id="size-constants" tabindex="-1">Size constants <a class="header-anchor" href="#size-constants" aria-label="Permalink to &quot;Size constants&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Constant</th><th>Value</th><th>Description</th></tr></thead><tbody><tr><td><code>defaultMaxChars</code></td><td>8,000</td><td>Default value of the <code>max_chars</code> parameter (~2000 tokens)</td></tr><tr><td><code>hardMaxChars</code></td><td>32,000</td><td>Upper bound of the <code>max_chars</code> parameter (~8000 tokens)</td></tr><tr><td><code>maxHTMLBodySize</code></td><td>1,048,576 (1MB)</td><td>Upper limit for reading the HTTP response body</td></tr></tbody></table><hr><h2 id="_5-duckduckgo-search-backend-web-search-go" tabindex="-1">5. DuckDuckGo Search Backend (<code>web_search.go</code>) <a class="header-anchor" href="#_5-duckduckgo-search-backend-web-search-go" aria-label="Permalink to &quot;5. DuckDuckGo Search Backend (\`web_search.go\`)&quot;">​</a></h2><h3 id="why-duckduckgo-was-chosen" tabindex="-1">Why DuckDuckGo was chosen <a class="header-anchor" href="#why-duckduckgo-was-chosen" aria-label="Permalink to &quot;Why DuckDuckGo was chosen&quot;">​</a></h3><p>After surveying the search backend choices of six mainstream frameworks: DuckDuckGo is the only backend <strong>supported by every framework with no API Key requirement</strong>, and its HTML endpoint (<code>html.duckduckgo.com/html/</code>) returns plain HTML — no JavaScript rendering is needed, and a standard HTTP client can handle it directly.</p><h3 id="request-flow" tabindex="-1">Request flow <a class="header-anchor" href="#request-flow" aria-label="Permalink to &quot;Request flow&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST https://html.duckduckgo.com/html/</span></span>
<span class="line"><span>Content-Type: application/x-www-form-urlencoded</span></span>
<span class="line"><span>User-Agent: harness9/1.0</span></span>
<span class="line"><span>Body: q=&lt;url-encoded-query&gt;</span></span></code></pre></div><p>Timeout controls:</p><ul><li><strong>Dial timeout</strong>: 10s (TCP handshake phase, <code>net.Dialer.Timeout</code>)</li><li><strong>Request timeout</strong>: 20s (Context deadline, covering DNS + dial + response read)</li></ul><p>The dual timeout addresses a known issue with <code>http.DefaultClient</code>: when only a context timeout is used, an extremely slow TCP handshake may not be interrupted promptly; an independent dial timeout guarantees responsiveness during the connection-establishment phase.</p><h3 id="html-parsing" tabindex="-1">HTML parsing <a class="header-anchor" href="#html-parsing" aria-label="Permalink to &quot;HTML parsing&quot;">​</a></h3><p><code>golang.org/x/net/html</code> (an existing indirect dependency, zero new additions) builds a full DOM tree via <code>html.Parse()</code>, recursively traversed to extract:</p><table tabindex="0"><thead><tr><th>Selector</th><th>Target content</th></tr></thead><tbody><tr><td><code>div.result</code> (excluding <code>div.result--more</code>)</td><td>Container for a single search result</td></tr><tr><td><code>a.result__a</code></td><td>Title text + href</td></tr><tr><td><code>a.result__snippet</code></td><td>Snippet text</td></tr></tbody></table><h3 id="ddg-redirect-url-decoding" tabindex="-1">DDG redirect URL decoding <a class="header-anchor" href="#ddg-redirect-url-decoding" aria-label="Permalink to &quot;DDG redirect URL decoding&quot;">​</a></h3><p>DuckDuckGo&#39;s links use a redirect format:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>href=&quot;/l/?uddg=https%3A%2F%2Fexample.com%2Fpath&amp;rut=...&quot;</span></span></code></pre></div><p><code>decodeUDDG()</code> extracts the real target URL from the <code>uddg</code> parameter, so the LLM receives the final URL that can be passed directly into <code>web_fetch</code>.</p><h3 id="testability-design" tabindex="-1">Testability design <a class="header-anchor" href="#testability-design" aria-label="Permalink to &quot;Testability design&quot;">​</a></h3><p>The <code>backendURL</code> field of the <code>WebSearchTool</code> struct points to the DDG endpoint by default, and can be replaced with a local <code>httptest.NewServer</code> address in tests, requiring no real network requests:</p><div class="language-go vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// production</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">tool </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> NewWebSearchTool</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// backendURL = &quot;https://html.duckduckgo.com/html/&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// testing</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">tool </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &amp;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">WebSearchTool</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{backendURL: server.URL}</span></span></code></pre></div><p>Likewise, <code>WebFetchTool</code>&#39;s <code>safetyCheck</code> field is replaced with a no-op in tests, allowing access to a 127.0.0.1 httptest server without triggering SSRF blocking.</p><hr><h2 id="_6-current-date-injection-internal-context-builder-go" tabindex="-1">6. Current Date Injection (<code>internal/context/builder.go</code>) <a class="header-anchor" href="#_6-current-date-injection-internal-context-builder-go" aria-label="Permalink to &quot;6. Current Date Injection (\`internal/context/builder.go\`)&quot;">​</a></h2><p><code>DefaultPromptBuilder.Build()</code> injects today&#39;s date into the base System Prompt:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>工作目录：/path/to/project</span></span>
<span class="line"><span>当前日期：2026-06-12</span></span></code></pre></div><p>Every <code>Build()</code> call executes <code>time.Now().Format(&quot;2006-01-02&quot;)</code> in real time, ensuring the Agent perceives the correct date in every session, so searches naturally carry the current year and avoid stale search results caused by training-cutoff drift.</p><hr><h2 id="_7-module-structure" tabindex="-1">7. Module Structure <a class="header-anchor" href="#_7-module-structure" aria-label="Permalink to &quot;7. Module Structure&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>internal/tools/</span></span>
<span class="line"><span>├── web_safety.go        # SSRF protection: isSafeURL (check chain + blockedCIDRs)</span></span>
<span class="line"><span>├── web_safety_test.go   # 19 test cases: IP ranges / scheme / DNS fail-closed / IPv6 / IPv6 ULA / IPv6 link-local</span></span>
<span class="line"><span>├── web_content.go       # HTML→Markdown pipeline: extractContent + extractPlainText + assemblePage (UTF-8-safe truncation)</span></span>
<span class="line"><span>├── web_content_test.go  # 5 test cases: basic conversion / truncation / fallback / oversized body / UTF-8-safe truncation</span></span>
<span class="line"><span>├── web_fetch.go         # WebFetchTool: HTTP GET + Content-Type branching</span></span>
<span class="line"><span>├── web_fetch_test.go    # 6 test cases: SSRF / HTML / text / unsupported / empty URL / 4xx</span></span>
<span class="line"><span>├── web_search.go        # WebSearchTool: DuckDuckGo POST + DOM parsing + decodeUDDG</span></span>
<span class="line"><span>└── web_search_test.go   # 6 test cases: DDG parsing / max_results / URL decoding / Execute / empty results</span></span></code></pre></div><p><strong>Dependency relationships:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>web_fetch.go ──────┐</span></span>
<span class="line"><span>                   ├──→ web_safety.go (isSafeURL)</span></span>
<span class="line"><span>web_search.go ─────┘</span></span>
<span class="line"><span>     │</span></span>
<span class="line"><span>     └──→ web_content.go (extractContent)  ──→ go-readability</span></span>
<span class="line"><span>                                           ──→ html-to-markdown</span></span>
<span class="line"><span>                                           ──→ golang.org/x/net/html (existing dependency)</span></span></code></pre></div><hr><h2 id="_8-configuration-and-usage" tabindex="-1">8. Configuration and Usage <a class="header-anchor" href="#_8-configuration-and-usage" aria-label="Permalink to &quot;8. Configuration and Usage&quot;">​</a></h2><p>Both tools are automatically registered when harness9 starts, and can be used by the main agent and all Sub-Agents with zero configuration required.</p><p><strong>Typical search flow:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>User: search for Go 1.25&#39;s new features</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Agent:</span></span>
<span class="line"><span>  1. web_search(&quot;Go 1.25 release notes&quot;) → get the result list</span></span>
<span class="line"><span>  2. web_fetch(&quot;https://go.dev/doc/go1.25&quot;) → get detailed content</span></span>
<span class="line"><span>  3. answer the user based on the fetched content</span></span></code></pre></div><p><strong>Sub-Agent delegation (research scenario):</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>@general-purpose search for LangGraph&#39;s latest checkpoint mechanism and summarize the key APIs</span></span></code></pre></div><p>The <code>general-purpose</code> Sub-Agent inherits all of the main agent&#39;s tools, including <code>web_search</code> and <code>web_fetch</code>, and can independently complete multi-round search + fetch + summarize, reporting back only the conclusion to the main context.</p><hr><h2 id="_9-limitations-and-caveats" tabindex="-1">9. Limitations and Caveats <a class="header-anchor" href="#_9-limitations-and-caveats" aria-label="Permalink to &quot;9. Limitations and Caveats&quot;">​</a></h2><ul><li><strong>DuckDuckGo rate limiting</strong>: no official SLA; high-frequency calls may trigger temporary blocking. For stable, high-frequency search, consider configuring Brave Search or Tavily via environment variables (pending P2 backend interface implementation)</li><li><strong>JavaScript-rendered pages</strong>: <code>web_fetch</code> uses plain HTTP requests and does not execute JavaScript, so dynamically rendered SPA content cannot be fetched</li><li><strong><code>go-readability</code> deprecation notice</strong>: currently using <code>github.com/go-shiori/go-readability</code>, which the author has marked deprecated; future migration to <code>codeberg.org/readeck/go-readability/v2</code> is recommended</li><li><strong>1MB size limit</strong>: pages larger than 1MB are rejected with an error</li></ul><hr><h2 id="_10-reference-implementations" tabindex="-1">10. Reference Implementations <a class="header-anchor" href="#_10-reference-implementations" aria-label="Permalink to &quot;10. Reference Implementations&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Framework</th><th>Strategy</th><th>Key characteristics</th></tr></thead><tbody><tr><td>OpenHarness</td><td>Minimal built-in</td><td>DuckDuckGo HTML parsing + self-implemented HTML→plain text, 12000-character truncation</td></tr><tr><td>OpenClaw</td><td>Pluggable hybrid</td><td>Mozilla Readability + htmlToMarkdown, 5+ search backends with cascading fallback</td></tr><tr><td>HermesAgent</td><td>Full-featured</td><td>8 backends, LLM content compaction pipeline (Gemini Flash, supports 2M-character chunking)</td></tr><tr><td>Claude Agent SDK</td><td>Officially built-in</td><td>Native <code>WebSearch</code>/<code>WebFetch</code> tools; research-agent example demonstrates Sub-Agent parallel research pattern</td></tr></tbody></table><p>For detailed research, see <code>docs/技术调研/web-search-capability.md</code> (local research document, not published with the repository).</p>`,88)])])}const g=t(i,[["render",o]]);export{u as __pageData,g as default};
